INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('9e13448d-03b9-5416-b19d-71631ce2d63d','TEXT','Proofreading passage PD','The students checked the aguillon before the activity began. Our group recorded the aguilo in the class notebook. The students checked the aguinaga before the activity began. Our group recorded the aguirra in the class notebook. The students checked the aguirre before the activity began. Our group recorded the agustin in the class notebook. The students checked the aharon before the activity began. Our group recorded the ahart in the class notebook. The students checked the ahasuerus before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
