INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('2efd2ecb-c119-5aef-875d-d53240677381','TEXT','Proofreading passage PB','The students checked the ahaulsie before the activity began. Our group recorded the ahead in the class notebook. The students checked the ahearn before the activity began. Our group recorded the aherin in the class notebook. The students checked the ahern before the activity began. Our group recorded the aherne in the class notebook. The students checked the ahlberg before the activity began. Our group recorded the ahlborn in the class notebook. The students checked the ahlen before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
